 const W=manifest.width,H=manifest.height,cache=new Map(),stats={fetches:0,encodedBytes:0,decodedBytes:0,peakDecodedBytes:0,decodes:0,evictions:0,stale:0,published:0,activeLoads:0,peakLoads:0};let generation=0,disposed=false,controller=null,queue=Promise.resolve(),latestState=null,activeKey=null,preparing=null;
 const sampler=createLightingSampler({night:[.4,.47,.6],schedule:{dawnStart:240,dayStart:540,duskStart:1020,nightStart:1260}}),frame=createFrame();
 function validate(s){const[cx,cy,w,h]=s.camera;if(!s.camera.every(Number.isInteger)||cx<0||cy<0||w<=0||h<=0||cx+w>W||cy+h>H||![s.elapsedMs,s.minutes].every(Number.isFinite)||s.elapsedMs<0)throw Error('frame-contract');}
